  assert.ok(decodeSnapshot(JSON.stringify(valid)));
  for (const key of Object.keys(valid)) {
    const missing: Record<string, unknown> = { ...valid };
    delete missing[key];
    assert.equal(decodeSnapshot(JSON.stringify(missing)), null, `missing ${key}`);
  }
